        add("ads_load", "Load test ad", "Charger une publicité de test", "Testanzeige laden", "Cargar anuncio de prueba", "Carregar anúncio de teste", "Carica annuncio di test");
        add("ads_watch", "Watch an ad · +35 gold", "Voir une publicité · +35 pièces d’or", "Anzeige ansehen · +35 Gold", "Ver anuncio · +35 monedas de oro", "Ver anúncio · +35 moedas de ouro", "Guarda annuncio · +35 monete d’oro");
        add("ads_reward_note", "Optional. 35 gold only after the reward event. Closing early gives nothing.", "Facultatif. 35 pièces d’or uniquement après l’événement de récompense. Fermer trop tôt ne donne rien.", "Optional. 35 Gold erst nach dem Belohnungsereignis. Frühes Schließen bringt nichts.", "Opcional. 35 monedas de oro solo tras el evento de recompensa. Cerrar antes no da nada.", "Opcional. 35 moedas de ouro só após o evento de recompensa. Fechar antes não dá nada.", "Facoltativo. 35 monete d’oro solo dopo l’evento premio. Chiudere prima non dà nulla.");
